task:
Объявите переменные:
int health = 100;
double armor = 45.5;
unsigned char level = 5;
Выведите их значения и размеры в байтах через sizeof:
Health: 100 (4 bytes)
Armor: 45.50 (8 bytes)
Level: 5 (1 bytes)

initialCode:
#include <stdio.h>

int main(void) {
    // Объявите health, armor, level и напечатайте результат:

    return 0;
}

solution:
#include <stdio.h>

int main(void) {
    int health = 100;
    double armor = 45.5;
    unsigned char level = 5;

    printf("Health: %d (%zu bytes)\n", health, sizeof(health));
    printf("Armor: %.2f (%zu bytes)\n", armor, sizeof(armor));
    printf("Level: %u (%zu bytes)\n", level, sizeof(level));
    return 0;
}

