#include <stdio.h>

static inline int clamp(int val, int min, int max) {
    if (val < min) return min;
    if (val > max) return max;
    return val;
}

int main(void) {
    printf("Clamped 1: %d\n", clamp(150, 0, 100));
    printf("Clamped 2: %d\n", clamp(-20, 0, 100));
