int main(void) {
    unsigned int flags = 0;
    flags |= (1 << 2);
    flags |= (1 << 4);
    printf("Flags with bits 2 and 4: %u\n", flags);

    flags &= ~(1 << 2);
    printf("Flags after clearing bit 2: %u\n", flags);
    return 0;
}

